syntax:
To handle constructor order in inheritance, define constructors in both base and derived classes, and use the initialization list in derived classes to explicitly call base constructors. For example:

class Base {
public:
    Base() {}  // Base default constructor
    Base(const Base& other) {}  // Base copy constructor
};

class Derived : public Base {
public:
    Derived() : Base() {}  // Calls Base constructor first
    Derived(const Derived& other) : Base(other) {}  // Calls Base copy constructor
};  // Practical usage note: Always use the initialization list for efficiency and to ensure base class initialization before derived class logic.

code_example:
#include <iostream>

class ZooAnimal {  // Base class representing a general zoo animal
public:
    ZooAnimal() { std::cout << "ZooAnimal constructor\n"; }  // Default constructor
    ZooAnimal(const ZooAnimal& other) { std::cout << "ZooAnimal copy constructor\n"; }  // Copy constructor
};

class Bear : public ZooAnimal {  // Derived class for a specific animal
public:
    Bear() { std::cout << "Bear constructor\n"; }  // Default constructor
    Bear(const Bear& other) : ZooAnimal(other) { std::cout << "Bear copy constructor\n"; }  // Copy constructor, explicitly calls base
};

int main() {
    Bear b1;  // Creates a Bear object, invoking constructors in order
    Bear b2 = b1;  // Copies b1 to b2, invoking copy constructors in order
    return 0;
}
